class Strings(private val values: Map<Message, String>) {
    operator fun invoke(message: Message, vararg arguments: Pair<String, Any?>): String {
        val parameters = arguments.toMap()
        return Regex("\\{\\{(\\w+)\\}\\}").replace(values.getValue(message)) { match ->
            parameters[match.groupValues[1]]?.toString() ?: match.value
        }
    }
}

val LocalStrings = staticCompositionLocalOf<Strings> { error("Missing localized strings") }

@Composable
fun useStrings(): Strings {
    val values = Message.entries.associateWith { stringResource(it.resource) }
    return androidx.compose.runtime.remember(values) { Strings(values) }
}
